import React from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';

export default function Home() {
  return (
    <>
      <style>{`
        /* Global Reset & Base Layout */
        .home-container {
          font-family: 'Inter', sans-serif;
          color: #0f172a;
          background-color: #f8fafc;
          overflow-x: hidden;
        }

        .home-container section {
          padding: 60px 8%;
        }

        /* 1. Hero Section */
        .home-container .hero-section {
          background: linear-gradient(135deg, #020617 0%, #0f172a 100%);
          color: #ffffff;
          display: flex;
          align-items: center;
          justify-content: space-between;
          padding: 80px 8%;
          gap: 40px;
        }

        .home-container .hero-content {
          max-width: 600px;
        }

        .home-container .badge {
          display: inline-flex;
          align-items: center;
          gap: 8px;
          background: rgba(255, 255, 255, 0.1);
          padding: 6px 14px;
          border-radius: 20px;
          font-size: 14px;
          margin-bottom: 20px;
          border: 1px solid rgba(255, 255, 255, 0.15);
        }

        .home-container .hero-content h1 {
          font-size: 42px;
          line-height: 1.2;
          font-weight: 800;
          margin-bottom: 20px;
        }

        .home-container .highlight-text {
          color: #06b6d4;
        }

        .home-container .hero-content p {
          color: #94a3b8;
          font-size: 16px;
          margin-bottom: 30px;
          line-height: 1.6;
        }

        .home-container .hero-buttons {
          display: flex;
          gap: 16px;
        }

        .home-container .btn-primary {
          background-color: #06b6d4;
          color: #ffffff;
          border: none;
          padding: 12px 24px;
          font-weight: 600;
          border-radius: 8px;
          cursor: pointer;
          transition: background 0.2s;
        }

        .home-container .btn-primary:hover {
          background-color: #0891b2;
        }

        .home-container .btn-secondary {
          background: transparent;
          color: #ffffff;
          border: 1px solid rgba(255, 255, 255, 0.3);
          padding: 12px 24px;
          font-weight: 600;
          border-radius: 8px;
          cursor: pointer;
        }

        .home-container .hero-image-wrapper {
          position: relative;
          max-width: 450px;
        }

        .home-container .hero-img-placeholder {
          font-size: 100px;
          background: rgba(255, 255, 255, 0.05);
          padding: 60px;
          border-radius: 20px;
          text-align: center;
          border: 1px solid rgba(255, 255, 255, 0.1);
        }

        /* 2. Trusted Companies */
        .home-container .trusted-section {
          text-align: center;
          background: #ffffff;
          padding: 40px 8%;
          border-bottom: 1px solid #e2e8f0;
        }

        .home-container .trusted-title {
          font-size: 14px;
          color: #64748b;
          text-transform: uppercase;
          letter-spacing: 1px;
          margin-bottom: 20px;
          font-weight: 600;
        }

        .home-container .company-logos {
          display: flex;
          justify-content: space-around;
          align-items: center;
          flex-wrap: wrap;
          gap: 30px;
          font-weight: 700;
          font-size: 20px;
          color: #475569;
        }

        /* 3. Core Pillars */
        .home-container .pillars-section {
          text-align: center;
          background: #ffffff;
        }

        .home-container .pillars-section h2, 
        .home-container .tracks-section h2, 
        .home-container .why-section h2, 
        .home-container .testimonials-section h2 {
          font-size: 32px;
          font-weight: 700;
          margin-bottom: 40px;
        }

        .home-container .pillars-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
          gap: 24px;
        }

        .home-container .pillar-card {
          background: #f8fafc;
          padding: 30px;
          border-radius: 12px;
          border: 1px solid #e2e8f0;
          text-align: left;
        }

        .home-container .pillar-icon {
          font-size: 28px;
          margin-bottom: 16px;
          background: #e0f2fe;
          display: inline-block;
          padding: 12px;
          border-radius: 8px;
        }

        .home-container .pillar-card h3 {
          font-size: 18px;
          margin-bottom: 10px;
        }

        .home-container .pillar-card p {
          color: #64748b;
          font-size: 14px;
          line-height: 1.5;
        }

        /* 4. Top Tech Tracks */
        .home-container .tracks-section {
          text-align: center;
        }

        .home-container .tracks-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
          gap: 30px;
          text-align: left;
        }

        .home-container .track-card {
          background: linear-gradient(135deg, #020617 0%, #0f172a 100%);
          color: #ffffff;
          padding: 35px;
          border-radius: 16px;
          display: flex;
          flex-direction: column;
          justify-content: space-between;
        }

        .home-container .track-header {
          display: flex;
          align-items: center;
          gap: 16px;
          margin-bottom: 20px;
        }

        .home-container .tech-logo {
          font-size: 36px;
        }

        .home-container .track-header h3 {
          font-size: 22px;
          margin: 0;
        }

        .home-container .track-subtitle {
          color: #94a3b8;
          font-size: 14px;
        }

        .home-container .track-desc {
          color: #94a3b8;
          font-size: 14px;
          margin-bottom: 24px;
          line-height: 1.5;
        }

        .home-container .track-tags {
          display: flex;
          flex-direction: column;
          gap: 8px;
          margin-bottom: 30px;
          font-size: 13px;
          color: #cbd5e1;
        }

        .home-container .btn-track-python, 
        .home-container .btn-track-java {
          background-color: #06b6d4;
          color: #ffffff;
          border: none;
          padding: 12px;
          font-weight: 600;
          border-radius: 8px;
          cursor: pointer;
          text-align: center;
          transition: background 0.2s;
        }

        .home-container .btn-track-python:hover, 
        .home-container .btn-track-java:hover {
          background-color: #0891b2;
        }

        /* 5. Why Learn with Vighnavi Academy */
        .home-container .why-section {
          background: #ffffff;
          text-align: center;
        }

        .home-container .why-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
          gap: 24px;
          text-align: left;
        }

        .home-container .why-item {
          display: flex;
          gap: 16px;
          align-items: flex-start;
          background: #f8fafc;
          padding: 20px;
          border-radius: 10px;
          border: 1px solid #e2e8f0;
        }

        .home-container .why-icon {
          font-size: 24px;
        }

        .home-container .why-item h4 {
          font-size: 16px;
          margin-bottom: 4px;
        }

        .home-container .why-item p {
          font-size: 13px;
          color: #64748b;
          margin: 0;
        }

        /* 6. Testimonials */
        .home-container .testimonials-section {
          text-align: center;
        }

        .home-container .testimonials-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
          gap: 24px;
          text-align: left;
        }

        .home-container .testimonial-card {
          background: #ffffff;
          padding: 30px;
          border-radius: 12px;
          border: 1px solid #e2e8f0;
          display: flex;
          flex-direction: column;
          justify-content: space-between;
        }

        .home-container .quote {
          font-size: 36px;
          color: #06b6d4;
          line-height: 0.5;
          margin-bottom: 10px;
        }

        .home-container .testimonial-text {
          font-size: 14px;
          color: #334155;
          line-height: 1.6;
          margin-bottom: 20px;
        }

        .home-container .student-info {
          display: flex;
          align-items: center;
          gap: 12px;
        }

        .home-container .placeholder-avatar {
          width: 40px;
          height: 40px;
          background-color: #06b6d4;
          color: white;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          font-weight: bold;
          font-size: 14px;
        }

        .home-container .student-info h5 {
          font-size: 15px;
          margin: 0;
        }

        .home-container .student-info p {
          font-size: 12px;
          color: #64748b;
          margin: 0;
        }

        .home-container .carousel-dots {
          display: flex;
          justify-content: center;
          gap: 8px;
          margin-top: 30px;
        }

        .home-container .dot {
          width: 8px;
